    de = max(x1 - xf, xf - x2, 0) + max(y1 - yf, yf - y2, 0)
    if ds < to_start[ci]:
        to_start[ci] = ds
    if de < to_end[ci]:
        to_end[ci] = de

best_answer = abs(xi - xf) + abs(yi - yf)
dist = to_start[:]
used = [False] * c

for _ in range(c):
    u = -1
    best = best_answer
    for i in range(c):
        if not used[i] and dist[i] < best:
            best = dist[i]
            u = i

